import { callTool } from "./server.mjs";

async function check(desc, fn) {
  try { await fn(); console.log("PASS:", desc); }
  catch (e) { console.log("FAIL:", desc, "->", e.message); }
}

await check("first page uses c0 implicitly", async () => {
  const r = JSON.parse((await callTool("audit_page", { limit: 2 })).content[0].text);
  if (r.records.length !== 2) throw new Error("len");
  if (r.next_cursor !== "c2") throw new Error("cursor " + r.next_cursor);
});

await check("explicit c0 works", async () => {
  const r = JSON.parse((await callTool("audit_page", { limit: 2, cursor: "c0" })).content[0].text);
  if (r.records[0].id !== "a1") throw new Error("first id");
});

await check("later page returns null next_cursor at end", async () => {
  const r = JSON.parse((await callTool("audit_page", { limit: 3, cursor: "c3" })).content[0].text);
  if (r.records.length !== 1) throw new Error("len " + r.records.length);
  if (r.next_cursor !== null) throw new Error("cursor " + r.next_cursor);
});

await check("reject unknown cursor", async () => {
  let err;
  try { await callTool("audit_page", { limit: 1, cursor: "xyz" }); }
  catch (e) { err = e; }
  if (!err) throw new Error("no error");
});

await check("reject out of range cursor", async () => {
  let err;
  try { await callTool("audit_page", { limit: 1, cursor: "c99" }); }
  catch (e) { err = e; }
  if (!err) throw new Error("no error");
});

await check("reject invalid limit low", async () => {
  let err;
  try { await callTool("audit_page", { limit: 0 }); }
  catch (e) { err = e; }
  if (!err) throw new Error("no error");
});

await check("reject invalid limit high", async () => {
  let err;
  try { await callTool("audit_page", { limit: 4 }); }
  catch (e) { err = e; }
  if (!err) throw new Error("no error");
});

await check("reject extra fields", async () => {
  let err;
  try { await callTool("audit_page", { limit: 1, foo: "bar" }); }
  catch (e) { err = e; }
  if (!err) throw new Error("no error");
});

await check("reject unknown tool", async () => {
  let err;
  try { await callTool("bogus", {}); }
  catch (e) { err = e; }
  if (!err) throw new Error("no error");
  if (err.code !== -32601) throw new Error("wrong code " + err.code);
});

await check("reject missing limit", async () => {
  let err;
  try { await callTool("audit_page", {}); }
  catch (e) { err = e; }
  if (!err) throw new Error("no error");
});
